package mapper;import entity.ChiTietToaThuoc;import java.sql.ResultSet;import java.sql.SQLException;public class ChiTietToaThuocMapper implements RowMapper<ChiTietToaThuoc> {    @Override    public ChiTietToaThuoc mapper(ResultSet rs) {        try {            String maChiTiet = rs.getString("maChiTiet");            String maToaThuoc = rs.getString("maToaThuoc");            String maThuoc = rs.getString("maThuoc");            int soNgay = rs.getInt("soNgay");            String cachSuDung = rs.getString("cachSuDung");            int tongSo = rs.getInt("tongSo");            long donGia = rs.getLong("donGia");            long thanhTien = rs.getLong("thanhTien");            return new ChiTietToaThuoc(maChiTiet, maToaThuoc, maThuoc, soNgay, cachSuDung, tongSo, donGia, thanhTien);        } catch (SQLException e) {            return null;        }    }}